from __future__ import annotations
from datetime import datetime, timezone
from re import sub
from app.interview_catalog_phase2 import PHASE2_CAREER_FAMILIES
from app.interview_catalog_phase2_more import PHASE2_MORE_CAREER_FAMILIES
from app.interview_catalog_phase2_final import PHASE2_FINAL_CAREER_FAMILIES
CATALOG_VERSION=2
CAREER_FAMILIES={"software-platform":["Software Engineer","Frontend Engineer","Backend Engineer","Full Stack Engineer","DevOps Engineer","Site Reliability Engineer","Platform Engineer","Cloud Engineer","QA Engineer","Security Engineer"],"data-ai":["Data Analyst","Data Engineer","Data Scientist","Machine Learning Engineer","AI Engineer","Business Intelligence Analyst","Analytics Engineer","Database Administrator","Research Scientist","MLOps Engineer"],"it-support":["Technical Support Engineer","IT Support Specialist","Systems Administrator","Network Engineer","NOC Engineer","SOC Analyst","Help Desk Technician","Desktop Support Engineer","Solutions Engineer","Implementation Engineer"],"healthcare":["Registered Nurse","Licensed Practical Nurse","Medical Assistant","Physical Therapist","Occupational Therapist","Pharmacist","Radiologic Technologist","Respiratory Therapist","Dental Hygienist","Healthcare Administrator"],"business-finance":["Accountant","Financial Analyst","Auditor","Controller","Bookkeeper","Investment Analyst","Risk Analyst","Compliance Analyst","Operations Analyst","Business Analyst"],"product-project":["Product Manager","Product Owner","Project Manager","Program Manager","Scrum Master","Technical Program Manager","Business Operations Manager","Strategy Manager","Chief of Staff","Operations Manager"],"sales-customer":["Account Executive","Sales Development Representative","Customer Success Manager","Account Manager","Sales Engineer","Customer Support Specialist","Retail Sales Associate","Business Development Manager","Partnerships Manager","Client Services Manager"],"marketing-design":["Marketing Manager","Content Strategist","SEO Specialist","Social Media Manager","Brand Manager","Graphic Designer","UX Designer","UI Designer","UX Researcher","Product Designer"],"education-public-service":["Teacher","School Counselor","Instructional Designer","Academic Advisor","Professor","Social Worker","Case Manager","Nonprofit Program Manager","Public Policy Analyst","Government Program Analyst"],"skilled-trades":["Electrician","Plumber","HVAC Technician","Automotive Technician","Welder","Carpenter","Machinist","Industrial Maintenance Technician","Construction Supervisor","Field Service Technician"]}
for expansion in (PHASE2_CAREER_FAMILIES,PHASE2_MORE_CAREER_FAMILIES,PHASE2_FINAL_CAREER_FAMILIES):CAREER_FAMILIES.update(expansion)
FAMILY_SCENARIOS={"software-platform":["debugged a difficult production problem","improved reliability or performance","made a technical tradeoff","reduced repeated operational work","worked across teams on a technical dependency","handled an incident under pressure","improved developer or user experience","introduced automation safely"],"data-ai":["turned unclear data into a decision","found and corrected a data-quality issue","explained a complex finding to a nontechnical audience","validated a model or analysis","designed a reliable data pipeline","balanced speed with analytical rigor","worked with incomplete information","improved trust in reporting or metrics"],"it-support":["resolved a difficult customer or user issue","diagnosed a problem with incomplete information","prevented a repeat incident","handled a high-priority escalation","explained a technical issue clearly","balanced multiple urgent requests","documented a reusable troubleshooting path","worked with engineering or vendors to solve a problem"],"healthcare":["made a careful decision under pressure","handled a difficult patient or family interaction","noticed and escalated a safety concern","coordinated care across a team","protected accuracy while moving quickly","educated someone about a care plan","handled competing priorities","improved a process that affected patient experience"],"business-finance":["found a meaningful discrepancy","improved the accuracy of a process","explained financial information to a stakeholder","made a decision with incomplete information","managed a deadline with high accuracy requirements","reduced risk or strengthened controls","improved a recurring workflow","challenged an assumption using evidence"],"product-project":["aligned stakeholders with competing priorities","recovered a project that was off track","made a difficult prioritization decision","handled scope change","used customer or operational evidence to change direction","managed a dependency or risk","influenced without direct authority","defined success for an ambiguous initiative"],"sales-customer":["won or retained a difficult customer","handled an objection","recovered a strained customer relationship","identified an unmet customer need","balanced customer needs with business constraints","used data to improve your approach","partnered across teams to close a gap","handled a high-pressure customer situation"],"marketing-design":["turned an ambiguous brief into a clear direction","used research or data to change a creative decision","handled conflicting stakeholder feedback","improved a campaign or design through iteration","defended a decision with evidence","worked within a difficult constraint","measured whether your work succeeded","balanced user needs with business goals"],"education-public-service":["supported someone through a difficult situation","adapted your approach for different needs","handled conflict constructively","used evidence to improve an outcome","coordinated across multiple stakeholders","managed competing priorities","protected confidentiality or trust","improved access, participation, or understanding"],"skilled-trades":["diagnosed a difficult equipment or field problem","prevented a safety issue","completed high-quality work under time pressure","explained a repair or technical decision to a customer","found the root cause of a recurring failure","worked around an unexpected constraint safely","improved a maintenance or installation process","coordinated with other trades or teams"]}
DEFAULT_SCENARIOS=["solved a difficult problem","handled a high-pressure situation","worked with a difficult customer, client, patient, student, or stakeholder","improved a process or workflow","caught or prevented an important mistake","balanced competing priorities","worked effectively with a team","took ownership of an outcome"]
for family in CAREER_FAMILIES:FAMILY_SCENARIOS.setdefault(family,DEFAULT_SCENARIOS)
UNIVERSAL_QUESTIONS=[("motivation","Why are you interested in working as {article} {role}, and what makes this role a strong next step for you?"),("strength","What is one strength you would bring to {article} {role} position, and what evidence best demonstrates it?"),("growth","Tell me about a skill you had to develop to become more effective in your work."),("reflection","Tell me about a mistake or setback. What did you learn, and what did you change afterward?")]
def slugify(value:str)->str:return sub(r"[^a-z0-9]+","-",value.lower()).strip("-")
def indefinite_article(role:str)->str:return "an" if role[:1].lower() in "aeiou" else "a"
def _question(question_id,text,category,competencies,difficulty="standard"):return {"question_id":question_id,"text":text,"category":category,"competencies":competencies,"difficulty":difficulty,"active":True}
def build_career_document(role,family):
 questions=[]
 for index,scenario in enumerate(FAMILY_SCENARIOS[family],1):questions.append(_question(f"behavioral-{index:02d}",f"Tell me about a time you {scenario}. What was the situation, what did you personally do, and what changed as a result?","behavioral",["ownership","specificity","impact","communication"],"standard" if index<=5 else "stretch"))
 article=indefinite_article(role)
 for index,(category,template) in enumerate(UNIVERSAL_QUESTIONS,1):questions.append(_question(f"{category}-{index:02d}",template.format(role=role,article=article),category,["communication","self-awareness","role-alignment"]))
 return {"schema_version":1,"catalog_version":CATALOG_VERSION,"slug":slugify(role),"title":role,"family":family,"aliases":[],"active":True,"questions":questions,"question_count":len(questions),"updated_at":datetime.now(timezone.utc)}
def build_catalog():
 documents=[];seen=set()
 for family,roles in CAREER_FAMILIES.items():
  for role in roles:
   slug=slugify(role)
   if slug not in seen:seen.add(slug);documents.append(build_career_document(role,family))
 return documents
